describe('Popover Toggle on Button Click', () => {
  beforeEach(() => {
    cy.visit('/popover-toggle');
  });

  it('should toggle popover on button click and display content when visible', () => {
    // Verify popover is not visible initially
    cy.get('[data-testid="popover-button"]').should('be.visible');
    cy.get('[data-testid="popover-content"]').should('not.exist');

    // Click the button to open popover
    cy.get('[data-testid="popover-button"]').click();

    // Verify popover is now visible
    cy.get('[data-testid="popover-content"]').should('be.visible');

    // Verify popover content is displayed
    cy.get('[data-testid="popover-content"]').should('contain', 'Popover content');

    // Verify close button is present
    cy.get('[data-testid="popover-close-button"]').should('be.visible');

    // Click close button to hide popover
    cy.get('[data-testid="popover-close-button"]').click();

    // Verify popover is hidden
    cy.get('[data-testid="popover-content"]').should('not.exist');

    // Verify button is still visible
    cy.get('[data-testid="popover-button"]').should('be.visible');
  });

  it('should not toggle popover when button is disabled', () => {
    // Verify popover is not visible initially
    cy.get('[data-testid="popover-button"]').should('be.visible');
    cy.get('[data-testid="popover-content"]').should('not.exist');

    // Disable button
    cy.get('[data-testid="popover-button"]').should('be.visible');
    cy.get('[data-testid="popover-button"]').click();

    // Verify button is now disabled
    cy.get('[data-testid="popover-button"]').should('have.attr', 'disabled');

    // Verify popover is still not visible
    cy.get('[data-testid="popover-content"]').should('not.exist');

    // Verify button is still visible but disabled
    cy.get('[data-testid="popover-button"]').should('be.visible');
    cy.get('[data-testid="popover-button"]').should('have.attr', 'disabled');

    // Click disabled button - should not toggle popover
    cy.get('[data-testid="popover-button"]').click();

    // Verify popover is still not visible
    cy.get('[data-testid="popover-content"]').should('not.exist');

    // Verify button is still disabled
    cy.get('[data-testid="popover-button"]').should('have.attr', 'disabled');
  });
});
